1\", \"1984\".\n\nSo for 1984, the columns 10-12 contain:\n- Jan: 11.82, 12.65\n- Feb: 12.00, 12.80\n- Mar: 12.45, 13.36\n- Apr: 12.65, 13.64\n- May: 13.43, 14.41\n- June: 13.54, 14.49\n- July: 13.36, 14.25\n- Aug: 12.71, 13.54\n- Sept: 12.42, 13.37\n- Oct: 12.04, 13.02\n- Nov: 11.66, 12.40\n- Dec: 11.64, 12.47\n\nI'll develop a Python script to systematically extract and process this data.\n","signature":""},{"type":"toolRequest","id":"call_7cec0dacdfdc4df9a8dc6bc9","toolCall":{"status":"success","value":{"name":"shell","arguments":{"command":"python3 << 'EOF'\nimport json\nimport re\n\n# Load the 1980 bulletin (contains 1979 data)\nwith open('/app/resources/treasury_bulletin_1980_03.json') as f:\n    data1980 = json.load(f)\n\n# Load the 1985 bulletin (contains 1984 data)\nwith open('/app/resources/treasury_bulletin_1985_03.json') as f:\n    data1985 = json.load(f)\n\n# Extract 1979 data from element 966\nelements1980 = data1980['document']['elements']\ne1979 = elements1980[966]\ncontent1979 = e1979['content']\n\n# Extract 1984 data from element 333\nelements1985 = data1985['document']['elements']\ne1984 = elements1985[333]\ncontent1984 = e1984['content']\n\n# Parse 1979 data\n# Looking at the structure, for 1979 we need columns 7-9 (after 1969, 1972, 1975, 1978)\n# The table has groups of years: first row shows 1969, 1972, 1975, 1978\n# Second row shows 1970, 1973, 1976, 1979\n# Third row shows 1971, 1974, 1977, 1980\n\n# Let's extract using regex to parse the table\n# For 1979 (columns 7,8,9 in the second group of 3)\nimport re\n\n# Find all the data rows for 1979\n# The 1979 section starts after \"<td colspan=\\\"3\\\">1979</td>\"\n# We need to extract rows from the \"1970, 1973, 1976, 1979\" group\n\n# Let's extract using a different approach - parse manually\n# Split content by rows\nrows = content1979.split('<tr>')\n\n# The 1979 data is in the second section (after \"1970\", \"1973\", \"1976\", \"1979\" label)\n# Let's find the rows containing 1979\ntreasury_1979 = []\ncorporate_1979 = []\n\n# Looking at the parsed output:\n# The pattern shows years in groups of 4, each with 12 months\n# For 1979: it's the 4th column group (columns 7,8,9)\n# Looking at the data:\n#   - Oct: 9.44 (Treasury), 11.17 (Corporate)\n#   - Nov: 9.80 (Treasury), 11.52 (Corporate)\n#   - Dec: 9.58 (Treasury), 11.30 (Corporate)\n\n# The data is in the section labeled with 1979 in the 4th group of columns\n# Let's extract from the parsed content properly\n\n# Looking at the output from element 966:\n# The rows show: <td>Jan.</td><td>8.43 4/</td><td>9.47</td>... for 1979 columns\n\n# For 1979: columns 7-9 contain Treasury, Corporate, Municipal\n# The row structure is: <td>Month</td><td>col1</td><td>col2</td><td>col3</td>...<td>col9</td>...\n# Let's extract properly\n\n# Extract numeric values from the 1979 section (columns 7,8,9 after the 1979 label)\nimport re\n# Find rows with 1979 data\nlines = content1979.split('\\n')\nprint(\"Looking for 1979 data pattern...\")\n\n# The 1979 section is after the row with <td colspan=\"3\">1979</td>\n# And the data rows follow\n# Let me parse this more carefully\n\n# Use regex to extract from the 4th group of columns (indices 6,7,8 - 0-indexed)\n# But first find where 1979 starts\n\n# Alternative: manually map the data from visual inspection\n# 1979 Treasury (col 7): 8.43, 8.43, 8.45, 8.44, 8.55, 8.32, 8.35, 8.42, 8.68, 9.44, 9.80, 9.58\n# 1979 Corporate (col 8): 9.47, 9.52, 9.65, 9.69, 9.82, 9.51, 9.47, 9.57, 9.87, 11.17, 11.52, 11.30\n\n# Strip footnotes (like 4/, 5/)\ntreasury_1979 = [8.43, 8.43, 8.45, 8.44, 8.55, 8.32, 8.35, 8.42, 8.68, 9.44, 9.80, 9.58]\ncorporate_1979 = [9.47, 9.52, 9.65, 9.69, 9.82, 9.51, 9.47, 9.57, 9.87, 11.17, 11.52, 11.30]\n\n# For 1984: columns 10-12 (0-indexed: 9, 10, 11)\n# Looking at the parsed output from element 333:\n# The last group shows: 1975, 1978, 1981, 1984\n# Treasury (col 10): 11.82, 12.00, 12.45, 12.65, 13.43, 13.54, 13.36, 12.71, 12.42, 12.04, 11.66, 11.64\n# Corporate (col 11): 12.65, 12.80, 13.36, 13.64, 14.41, 14.49, 14.25, 13.54, 13.37, 13.02, 12.40, 12.47\n\ntreasury_1984 = [11.82, 12.00, 12.45, 12.65, 13.43, 13.54, 13.36, 12.71, 12.42, 12.04, 11.66, 11.64]\ncorporate_1984 = [12.65, 12.80, 13.36, 13.64, 14.41, 14.49, 14.25, 13.54, 13.37, 13.02, 12.40, 12.47]\n\nprint(\"1979 Treasury:\", treasury_1979)\nprint(\"1979 Corporate:\", corporate_1979)\nprint()\nprint(\"1984 Treasury:\", treasury_1984)\nprint(\"1984 Corporate:\", corporate_1984)\n\n# Calculate Pearson correlation coefficient\nimport math\n\ndef pearson_correlation(x, y):\n    n = len(x)\n    sum_x = sum(x)\n    sum_y = sum(y)\n    sum_xy = sum(xi * yi for xi, yi in zip(x, y))\n    sum_x2 = sum(xi ** 2 for xi in x)\n    sum_y2 = sum(yi ** 2 for yi in y)\n    \n    numerator = n * sum_xy - sum_x * sum_y\n    denominator = math.sqrt((n * sum_x2 - sum_x ** 2) * (n * sum_y2 - sum_y ** 2))\n    \n    return numerator / denominator\n\n# Calculate correlations\ncorr_1979 = pearson_correlation(treasury_1979, corporate_1979)\ncorr_1984 = pearson_correlation(treasury_1984, corporate_1984)\n\nprint(f\"\\n1979 Pearson correlation: {corr_1979}\")\nprint(f\"1984 Pearson correlation: {corr_1984}\")\n\nabs_diff = abs(corr_1979 - corr_1984)\nprint(f\"\\nAbsolute difference: {abs_diff}\")\nprint(f\"Rounded to 4 decimal places: {abs_diff:.4f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
